message:
statement: SELECT transaction_type, COUNT(*), SUM(amount) 
FROM transactions
GROUP BY transaction_type;

statement: SELECT user_id, amount 
FROM transactions 
WHERE amount IN (SELECT MAX(amount) FROM transactions GROUP BY user_id);

statement: SELECT user_id FROM transactions 
GROUP BY user_id 
HAVING SUM(amount) = (SELECT MAX(total) FROM (SELECT SUM(amount) AS total FROM transactions GROUP BY user_id) AS totals);

statement: UPDATE students
SET marks = 93
WHERE name = 'Rohit Patil';

statement: UPDATE students
SET marks = marks + 5
WHERE city = 'Pune';

