statement: DELETE FROM students
WHERE student_id NOT IN (
    SELECT MIN(student_id)
    FROM students
    GROUP BY name
);

statement: DELETE FROM students
WHERE student_id IN (
  SELECT student_id FROM (
    SELECT student_id FROM students ORDER BY marks ASC LIMIT 3
  ) AS temp
);

statement: DELETE FROM students
WHERE student_id NOT IN (
    SELECT MIN(student_id)
    FROM students
    GROUP BY name
);

