statement: CREATE TABLE departments (
    dept_id SERIAL PRIMARY KEY,
    dept_name VARCHAR(50) UNIQUE NOT NULL
);

statement: CREATE TABLE emp_details (
    detail_id SERIAL PRIMARY KEY,
    emp_id INT REFERENCES employees(emp_id) ON DELETE CASCADE,
    address TEXT
);

statement: SELECT department, COUNT(*), AVG(salary)
FROM employees
GROUP BY department;

statement: CREATE OR REPLACE FUNCTION total_employees()
RETURNS INTEGER AS $$
DECLARE
    total INT;
BEGIN
    SELECT COUNT(*) INTO total FROM employees;
    RETURN total;
END;
$$ LANGUAGE plpgsql;

statement: CREATE OR REPLACE FUNCTION make_uppercase()
RETURNS TRIGGER AS $$
BEGIN
    NEW.emp_name = UPPER(NEW.emp_name);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
